quests[31926] = { id = 31926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Antari", description = "You capitalized on my mistake last time and emerged victorious. This time, you will not be so fortunate, {race}.", sourceObjective = "Defeat Bloodknight Antari in a pet battle.", progress = "Your performance is astonishing.", completion = "You are a fool for thinking yourself better than me. I will crush you, I swear it!", sourceObjectiveStatus = "unverified-source-field" }
quests[31927] = { id = 31927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Northrend", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!", sourceObjective = "Defeat Beegle Blastfuse, Nearly Headless Jacob, Okrut Dragonwaste, and Gutretch in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31928] = { id = 31928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Payne", description = "In my opinion, my fellow tamers have been far too lenient on your training.\n\nTrue pet taming requires militaristic discipline. I shall honor you with the pleasure of seeing firsthand what that discipline can produce.\n\nCome to the Argent Tournament Grounds in Icecrown and see firsthand what you could become!", sourceObjective = "Defeat Major Payne in a pet battle.", progress = "Perhaps other methods may be useful in certain cases.", completion = "I was wrong about you, {name}. You've earned my respect as one of the finest adversaries I've ever faced. Don't go and think that I'll let you defeat me again next time, though!", sourceObjectiveStatus = "unverified-source-field" }
quests[31929] = { id = 31929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Northrend", description = "Outland's finest have fallen to your skill, but Northrend now awaits you!\n\nThere are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'drak.\n\nIf you are able to best all of them, then Northrend's Grand Master will surely challenge you!", sourceObjective = "Defeat Beegle Blastfuse, Nearly Headless Jacob, Okrut Dragonwaste, and Gutretch in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31930] = { id = 31930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Pandaria", description = "You must now face the toughest tamers in all of Azeroth, {name}. They make their home in Pandaria, training ground of the grand masters.\n\nThere are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes.\n\nIf you think yourself ready, seek out these champions of the trade and prove yourself!", sourceObjective = "Defeat Hyuna of the Shrines, Farmer Nishi, Mo'ruk, Courageous Yon, Seeker Zusshi, and Wastewalker Shu in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31931] = { id = 31931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beegle Blastfuse", description = "One of my chickens flew for just a moment yesterday, I swear. We're finally hitting the big time!\n\nOh, you'd like to battle again?", sourceObjective = "Defeat Beegle Blastfuse in a pet battle.", completion = "One day, when we're flying high above you, you'll be the loser!", sourceObjectiveStatus = "unverified-source-field" }
quests[31932] = { id = 31932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nearly Headless Jacob", description = "Time and time again you defy my wisdom. What is it that brings you back to these woods?\n\nAh, you wish to do battle once more. Very well then.", sourceObjective = "Defeat Nearly Headless Jacob in a pet battle.", progress = "Your intentions are clear.", completion = "Your risk has paid its due reward. Now begone!", sourceObjectiveStatus = "unverified-source-field" }
quests[31933] = { id = 31933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okrut Dragonwaste", description = "You dare interrupt our work? Then you must battle me again! Take out your pets, and I'll give you a taste of Hellscream's wrath!", sourceObjective = "Defeat Okrut Dragonwaste in a pet battle.", progress = "You...fool.", completion = "I dare you to continue to fight the inevitable. Dragons will once again serve our purposes, and you will fall to my hand in a pet battle. I swear on the Warchief's mantle that it will be so!", sourceObjectiveStatus = "unverified-source-field" }
quests[31934] = { id = 31934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutretch", description = "Me like fighting you. You not so easy like the others. We fight again?", sourceObjective = "Defeat Gutretch in a pet battle.", completion = "Me like fighting you, even if me lose.", sourceObjectiveStatus = "unverified-source-field" }
quests[31935] = { id = 31935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Payne", description = "The rebel {class} comes once again to test <his/her> might again that of a Grand Master. Your bravery will be your undoing this time!", sourceObjective = "Defeat Major Payne in a pet battle.", completion = "I applaud your tactics, but despise your victory. Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31936] = { id = 31936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Jinyu Princess\" Irrigation System", description = "<The back of the box features a caricature of a jinyu maiden surrounded by marketing copy.>\n\n\"Hey there, greenthumb. Are you pouting over parched pumpkins? Crying over crusty cabbage? Are your leeks lame and your melons melancholy?\n\nThen it's time you brought home the Jinyu Princess! She'll wash over your garden like a sweet spring rain, dousing that drought with a deep draught of...\"\n\n<It goes on like this for six paragraphs.>", sourceObjective = "Bring the \"Jinyu Princess\" Irrigation System to Farmer Yoon at Sunsong Ranch or Halfhill market.\n\nProvided item:", completion = "A sprinkler system? For the farm? Thank you, {name}! We can use this instead of that old watering can.\n\nThe \"Jinyu Princess\" eh? What's up with that?\n\n\n\nAlright, I don't even want to know. I'll get this installed right away!", sourceObjectiveStatus = "unverified-source-field" }
quests[31937] = { id = 31937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Thunder King\" Pest Repellers", description = "<An imposing image of a mogu face dominates this box, casting its gaze downward at neatly ordered rows of bold text.>\n\n\"DO NOT LET WEAK, DISGUSTING INSECTS INFEST YOUR GLORIOUS CROPS. CONQUER THEM WITH THE MIGHT OF THE THUNDER KING AND PROTECT YOUR LEGACY.\"\n\n<The rest of the space is dedicated to cartoon depictions of various insects crying out in lament or fleeing in terror.>", sourceObjective = "Bring the \"Thunder King\" Pest Repellers to Farmer Yoon at Sunsong Ranch or Halfhill Market.\n\nProvided item:", completion = "Pest repellers! You're a genius, {name}! We can finally stop using that ancient bug sprayer.\n\n\n\nAw yeah, Thunder King! That's what I'm talking about!\n\nI'll get this installed right away - those bugs won't know what hit 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[31938] = { id = 31938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Earth-Slasher\" Master Plow", description = "<The box art depicts a pandaren farmer of impossible physique standing proudly astride a widening rift in the earth, a mighty plow in his grasp. Cubs wrestle playfully on his shoulders and dangle from his muscular arms.\n\nAt his side, a stoic female - of equally impossible physique - balances a massive, overflowing cornucopia gracefully on her head while kicking a virmen in the face.>\n\n\"The Earth-Slasher. Master the land. Master your life.\"", sourceObjective = "Bring the \"Earth-Slasher\" Master Plow to Farmer Yoon at Sunsong Ranch or Halfhill Market.\n\nProvided item:", completion = "An Earth-Slasher master plow! I... I never thought I'd get to use one of these. Do you have any idea how much time this will save us?!\n\nI heard if you push the Earth-Slasher through twenty yards of solid rock, you end up with a sandbox and a citation from the Shado-Pan for causing an earthquake scare!\n\nThis is going to be AWESOME.", sourceObjectiveStatus = "unverified-source-field" }
quests[31941] = { id = 31941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squash Those Foul Odors", description = "Grandpa always said, \"A squash a week, and your tail won't reek.\"\n\n<Yoon subtly sniffs the air.>\n\nYup. I think it's been about a week. Could you help me plant a Jade Squash?", sourceObjective = "Plant a Jade Squash in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "You might want to have a little squash too, {name}. Just sayin'.", completion = "Well planted, {name}.\n\nNow we play the waiting game...", sourceObjectiveStatus = "unverified-source-field" }
quests[31942] = { id = 31942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Melon Time", description = "<Farmer Yoon looks up at the sky and sniffs the air.>\n\nHmm...\n\n<He licks his paw and holds it up in the air, sticks a toenail into the soil, and then inspects the length of his shadow.>\n\nYup. It's melon time.\n\nCould you grab some seeds and help me plant a Striped Melon?", sourceObjective = "Plant a Striped Melon in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "Hurry up! Melon time doesn't last forever!", completion = "That was close. We almost missed melon time.", sourceObjectiveStatus = "unverified-source-field" }
quests[31943] = { id = 31943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Which Berries? Witchberries.", description = "That young'un over there, Andi, is going to grow up to be a heck of a farmer some day. I can tell just by lookin' at him.\n\nI think I'll plant him some witchberries. Kids love witchberries - it'll be a nice surprise.", sourceObjective = "Plant Witchberries in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "The trick to a good witchberry crop is to wait until they're nice and sweet.\n\nIt's not as easy as it sounds. I remember when I was a just a cub, puckerin' on some not-even-half-ripe witchberries because I couldn't wait like Grandpa told me to.", completion = "Alright, witchberries! I can't wait!\n\nBut I'm gonna have to.", sourceObjectiveStatus = "unverified-source-field" }
quests[31944] = { id = 31944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Complete Your Training: The Final Test", description = "Welcome back, {name}.  The time has come for you to complete the last step of your training.  Head to the Training Grounds for your final test.", sourceObjective = "Go the the Training Grounds at the Peak of Serenity and complete your final test.", completion = "Well done, {name}.  Your training is now complete.  Feel free to return in the future to spar with the masters here to practice what you have learned.", sourceObjectiveStatus = "unverified-source-field" }
quests[31945] = { id = 31945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow VI: Gina's Vote", description = "My business is doomed! You see all of the Ironpaws at their cooking stations?\n\nTheir tasty dishes draw many of the customers to this market, but they're all out of scallions!\n\nIt may not look like much, but the scallion is an essential cooking ingredient. Without it, foods are less savory, less flavorful, and less aromatic.\n\nThis is terrible. I'm not getting another scallion shipment for a week!\n\nWait a second. You're a farmer, aren't you? You think you could help me?", sourceObjective = "Plant and harvest 1 Scallion, then deliver 5 Scallions to Gina Mudclaw.\n\nScallion Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Scallions.", progress = "Don't overlook the scallion. It may be small and innocuous, but it creates truly marvelous flavors.", completion = "Well, I'll be! I've certainly seen larger scallions, but this will do quite nicely. You've just saved our hides, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31946] = { id = 31946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mung's Vote III: The Great Carrot Caper", description = "Mung-Mung don't care who steals carrots. Only care what Mr. Mudclaw does to poor Mung-Mung when he finds his crop is ruined!\n\n<Mung-Mung rubs his chin thoughtfully.>\n\nWait! Mung-Mung have bright idea. You go and grow some juicycrunch carrots. Then, we take your carrots and pretend they are Mr. Mudclaw's.\n\nYes!", sourceObjective = "Plant and harvest 2 Juicycrunch Carrots, then deliver 10 Juicycrunch Carrots to Mung-Mung.\n\nJuicycrunch Carrot Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Juicycrunch Carrots.", progress = "Virmens love carrots, but they hate turnips. I hate turnips, too.", completion = "Whoa, these carrots look crunchy and juicy, {name}! Mung-Mung did not know you had such a green thumb.", sourceObjectiveStatus = "unverified-source-field" }
quests[31947] = { id = 31947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmer Fung's Vote III: Crazy For Cabbage", description = "<Farmer Fung is beaming with a radiant smile.>\n\nThanks to you, I got my precious yaks back! Unfortunately, I noticed that their time out in the wild left them rather gaunt.\n\nThey must be starving, but I don't feed my prize yaks just any regular old grass.\n\nNo sir, they eat only the leafiest green cabbages you can find here in the Valley.\n\nMy stores are a bit low. If you bring me some cabbages for my yaks, I will reward you handsomely.", sourceObjective = "Plant and harvest 3 Green Cabbages, then deliver 15 Green Cabbages to Farmer Fung.\n\nGreen Cabbage Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Green Cabbages.", progress = "I have pet nicknames for all of my yaks. There's Hairy, and Shaggy, and Fluffy, and Woolly, and...", completion = "I was expecting cabbages, but not cabbages of this quality! Oh my!\n\nA perfectly round head, large waxy leaves, a perfect gradient of emerald color...\n\n<Farmer Fung takes a bite out of the cabbage.>\n\nMmm, and sweet, crisp flavor! These is a beautiful cabbage, {name}. My yaks will certainly be spoiled by this tasty treat.", sourceObjectiveStatus = "unverified-source-field" }
quests[31948] = { id = 31948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nana's Vote II: The Sacred Springs", description = "You caught me at a good time, {name}. I was just hankering to make a fresh batch of Witchberry Julep.\n\nHave you ever heard of this wondrous brew?\n\nEach sip takes ten years off your face! How do you think I still look so good?\n\nAnyway, I need a special ingredient - thousand-year water - which can be collected from the mouth of the waterfall to the north.\n\nI'm afraid the journey is too treacherous for an old matron like me, but if you can get your hands on a pitcher, I'll let you share my brew.", sourceObjective = "Use the Empty Pitcher at the Golden Falls to collect Thousand-Year Water.", progress = "The water in this valley flows from the Vale of Eternal Blossoms to the north. It is said that these waters have wondrous, magical properties.", completion = "Found the falls, did you? Oh yes, I see you found the water. Wonderful!", sourceObjectiveStatus = "unverified-source-field" }
quests[31949] = { id = 31949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nana's Vote III: Witchberry Julep", description = "Now that we have the water, I can almost taste the icy cold witchberry julep!\n\nNow, we just need to find ourselves some sweet witchberries.\n\nMy grandson's berries this season have been total slop, so I need to seek a decent harvest elsewhere.\n\nSay, do you have any witchberries in the ground this year? How about you bring me some from your farm?\n\nIf your berries are up to the standard, we'll make ourselves a grand old batch of the old juice!", sourceObjective = "Plant and harvest 3 Witchberries, then deliver 15 Witchberries to Nana Mudclaw.\n\nWitchberry Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Witchberries.", progress = "Hurry it up, will ya? I'm an old woman. I don't have all the time in the world, and I want one more taste of the sauce before I croak!", completion = "<Nana Mudclaw scrutinizes a dark witchberry, then pops it into her mouth. Her face lights up.>\n\nLands alive! I haven't tasted such a sweet, juicy witchberry in years! Why, the only person who could grow berries like these was... Old Yoon, yer friend's grandpa.\n\n<Nana Mudclaw blushes.>\n\nOh that man was such a scamp! I still remember the summer days when we were young, eating these berries by the bushel without a care in the world.\n\nThank you for reminding me of an old friend, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31951] = { id = 31951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Aki", description = "You have fought hard and well against the trainers of Azeroth. Even the grand masters have fallen to your cunning tactics.\n\nI now await you in the Vale of Eternal Blossoms, for you have earned the privilege to face me in battle. Come, {name}, and let us see if you have what it takes to defeat me.", sourceObjective = "Defeat Aki the Chosen in a pet battle.", progress = "I have heard much about your techniques. Hopefully that does not alter the outcome of our bout.", completion = "You have emerged victorious. Continue your training and find challenges in other trainers like yourself. The journey is never truly complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[31952] = { id = 31952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Pandaria", description = "You must now face the toughest tamers in all of Azeroth, {name}. They make their home in Pandaria, training ground of the grand masters.\n\nThere are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes.\n\nIf you think yourself ready, seek out these champions of the trade and prove yourself!", sourceObjective = "Defeat Hyuna of the Shrines, Farmer Nishi, Mo'ruk, Courageous Yon, Seeker Zusshi, and Wastewalker Shu in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31953] = { id = 31953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Hyuna", description = "You seek to do battle once more? Very well, it will strengthen me to better protect the sacred sites of my people.", sourceObjective = "Defeat Hyuna of the Shrines in a pet battle.", progress = "You are a noble fighter.", completion = "You are very strong. Will you lend your skills to my efforts?", sourceObjectiveStatus = "unverified-source-field" }
quests[31954] = { id = 31954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Mo'ruk", description = "This time I'm gonna do the beating! You watch!", sourceObjective = "Defeat Mo'ruk in a pet battle.", progress = "No! Me win!", completion = "Next time you lose. I'm gonna beatcha!", sourceObjectiveStatus = "unverified-source-field" }
quests[31955] = { id = 31955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Nishi", description = "My pets continue to grow in strength thanks to the fertile land we train on. You don't stand a chance!", sourceObjective = "Defeat Farmer Nishi in a pet battle.", progress = "You're good, I'll give you that.", completion = "Wow! I'm not the only one that's been training!", sourceObjectiveStatus = "unverified-source-field" }
quests[31956] = { id = 31956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Yon", description = "If you think I am going to let you walk away with another victory in hand, you are sorely mistaken. This time, I will stand over you as the superior trainer!", sourceObjective = "Defeat Courageous Yon in a pet battle.", completion = "Fine. Victory is yours once more. Begone, I have much preparation to do before we meet again.", sourceObjectiveStatus = "unverified-source-field" }
quests[31957] = { id = 31957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Shu", description = "You venture into the heart of the wastes to face me again, only to suffer defeat at the hands of a true grand master. Noble, but foolish.", sourceObjective = "Defeat Wastewalker Shu in a pet battle.", completion = "In all my time as a grand master I've never faced one as determined as you. The others were right about you. You are a force to be reckoned with.", sourceObjectiveStatus = "unverified-source-field" }
quests[31958] = { id = 31958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Aki", description = "You wish to test yourself against me once more? Very well, let us fight.", sourceObjective = "Defeat Aki the Chosen in a pet battle.", progress = "The journey to greatness is never complete.", completion = "You are stronger and your skills more refined. Your journey continues.", sourceObjectiveStatus = "unverified-source-field" }
quests[31959] = { id = 31959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Empress' Gambit", description = "Grand Empress Shek'zeer has finally lost her patience with us. We have learned of an enormous army, massing in the shadows of the Heart of Fear, with orders to crush Klaxxi'vess.\n\nWe have been fortunate to hold out this long, but we cannot survive a siege of this scale.\n\nWakener, you have been invaluable to our efforts. Come, take your place on the field among we paragons.\n\nI will see you on the battlefield!", sourceObjective = "Report to Malik the Unscathed outside the Heart of Fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[31966] = { id = 31966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Cataclysm", description = "You have defeated Northrend's finest tamers, but you need more preparation before you are ready to face the grand masters of Pandaria. Ready yourself and hone your skills by defeating these elite tamers: Brok in Mount Hyjal, Bordin Steadyfist in Deepholm, and Goz Banefury in Twilight Highlands.\n\nOnce you have triumphed over them, you will be ready to journey to Pandaria to face the ultimate challenge.", sourceObjective = "Defeat Brok, Bordin Steadyfist, and Goz Banefury in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31967] = { id = 31967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Cataclysm", description = "Northrend has fallen to your hand, but you are not yet ready to face the grand masters of Pandaria. Defeat these tamers to harden your will for the coming challenges: Brok in Mount Hyjal, Bordin Steadyfist in Deepholm, and Goz Banefury in Twilight Highlands.\n\nOnly by defeating them will you be ready to journey to Pandaria.", sourceObjective = "Defeat Brok, Bordin Steadyfist, and Goz Banefury in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31970] = { id = 31970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Obalis", description = "You think yourself ready to challenge Pandaria? You truly believe that you can defeat the most powerful tamers in all of Azeroth?\n\nI shall be the judge of that notion, {race}. Face me atop the Vir'naal Dam in Uldum, and we shall see if you are truly ready.", sourceObjective = "Defeat Obalis in a pet battle.", progress = "I admire your passion, young one.", completion = "I have been proven wrong. You are prepared to face my greaters.", sourceObjectiveStatus = "unverified-source-field" }
quests[31971] = { id = 31971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Obalis", description = "I see the triumphant tamer returns to again test <himself/herself> against me. Very well. I accept your challenge.", sourceObjective = "Defeat Obalis in a pet battle.", progress = "Defeat is but a path to success.", completion = "By defeating me, I grow stronger. I urge you to be wary during our next encounter.", sourceObjectiveStatus = "unverified-source-field" }
quests[31972] = { id = 31972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brok", description = "I do not yet understand the plight of these creatures well enough to help them sufficiently. Perhaps another battle would strengthen our bond?", sourceObjective = "Defeat Brok in a pet battle.", completion = "Even in defeat I feel closer to my pets. Thank you for a worthy skirmish.", sourceObjectiveStatus = "unverified-source-field" }
quests[31973] = { id = 31973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bordin Steadyfist", description = "The natives have taught me the strength of the earth. I know it's unending endurance. Let us battle once more, and you'll see that I'm tougher than ever!", sourceObjective = "Defeat Bordin Steadyfist in a pet battle.", completion = "No, no, I just messed up. How about another go?", sourceObjectiveStatus = "unverified-source-field" }
quests[31974] = { id = 31974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goz Banefury", description = "The power of twilight flows through me. I am a god! You have no hope of defeating me!", sourceObjective = "Defeat Goz Banefury in a pet battle.", completion = "You fight with the wrath of my masters. Perhaps you and I aren't so different.", sourceObjectiveStatus = "unverified-source-field" }
quests[31975] = { id = 31975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Audrey Burnhep in Stormwind and see what's next in your new career as a tamer!", sourceObjective = "Report to Audrey Burnhep in Stormwind.", completion = "Let's see...where to send you next...", sourceObjectiveStatus = "unverified-source-field" }
quests[31976] = { id = 31976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning Champion", description = "Word of your skill is spreading. I suggest you return to your trainer, Audrey Burnhep, for further guidance.", sourceObjective = "Report to Audrey Burnhep in Stormwind.", completion = "Let's see...where to send you next...", sourceObjectiveStatus = "unverified-source-field" }
quests[31977] = { id = 31977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning Champion", description = "You belong in Outland with the other hotshots if ya ask me. Why don't ya go back to Varzok in Orgrimmar and see what's next in your new career as a tamer!", sourceObjective = "Report to Varzok in Orgrimmar.", completion = "I've been at work preparing your next set of challenges, {name}. Let us see if you are prepared...", sourceObjectiveStatus = "unverified-source-field" }
quests[31978] = { id = 31978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priorities!", description = "Just look at this mess! All that brew gone to waste!\n\nTaran Zhu warned us against speaking to you outsiders, but I'll take any help I can get.\n\nWe were on our way to Dawn's Blossom to deliver our brew when the fighting broke out. Now all of our brew has been lost!\n\nYou want to make it up to us? Maybe you can find some of our Honeybrew barrels that haven't been broken. Then it wouldn't be a complete loss.", sourceObjective = "Find 6 Barrels of Honeybrew in Honeydew Glade.", completion = "Well, it's not as much as I would have hoped, but it will have to do. I guess there is no sense in cryin' over spilled brew.", sourceObjectiveStatus = "unverified-source-field" }
quests[31980] = { id = 31980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Returning Champion", description = "Word of your skill is spreading. I suggest you return to your trainer, Varzok, for further guidance.", sourceObjective = "Report to Varzok in Orgrimmar.", completion = "I think I know just the right place to test you next.", sourceObjectiveStatus = "unverified-source-field" }
quests[31981] = { id = 31981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exceeding Expectations", description = "Run off to your trainer, Audrey Burnhep, in Stormwind. Perhaps she can find you more...worthwhile...challenges.", sourceObjective = "Report to Audrey Burnhep in Stormwind.", completion = "You really beat Grand Master Antari? Wow! I'm going to have to find you some really tough tamers to fight!", sourceObjectiveStatus = "unverified-source-field" }
quests[31982] = { id = 31982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exceeding Expectations", description = "Run off to your trainer, Varzok, in Orgrimmar. Perhaps he can find you more... worthwhile... challenges.", sourceObjective = "Report to Varzok in Orgrimmar.", completion = "There is only one place to test you next.", sourceObjectiveStatus = "unverified-source-field" }
quests[31983] = { id = 31983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brief Reprieve", description = "Well done, for an {race}. Now, get back to Orgrimmar and talk to that brute Varzok. Maybe he can point you somewhere very far away from my family.", sourceObjective = "Report to Varzok in Orgrimmar.", completion = "I think I know the next step you ought to take.", sourceObjectiveStatus = "unverified-source-field" }
quests[31984] = { id = 31984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brief Reprieve", description = "Well done, well done indeed! If you would, please report to Miss Audrey Burnhep in Stormwind.\n\nOh, and send her my regards. She's a beautiful young woman that could benefit from the company of an accomplished fighter such as myself.", sourceObjective = "Report to Audrey Burnhep in Stormwind.", completion = "Payne asked you to court me for him, didn't he? When is he ever going to learn?", sourceObjectiveStatus = "unverified-source-field" }
quests[31985] = { id = 31985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Triumphant Return", description = "You are now prepared as your trainer instructed. Travel back to Stormwind and have words with Audrey Burnhep. She will guide you further.", sourceObjective = "Report to Audrey Burnhep in Stormwind.", completion = "I take it you met Obalis? He's a wonderful fellow, once you get past his rough exterior.", sourceObjectiveStatus = "unverified-source-field" }
quests[31986] = { id = 31986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Triumphant Return", description = "You are now prepared as your trainer instructed. Travel back to Orgrimmar and have words with Varzok. He will guide you further.", sourceObjective = "Report to Varzok in Orgrimmar.", completion = "You are now prepared for a true test of your skill in battle. Are you up to it?", sourceObjectiveStatus = "unverified-source-field" }
quests[31987] = { id = 31987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theramore" }
quests[31988] = { id = 31988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Selected Scenario" }
quests[31989] = { id = 31989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Peak of Serenity - Complete Your Training", description = "The time has come for you to return to the Peak of Serenity to complete your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", sourceObjective = "Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.", completion = "Welcome back, {name}.  It is time for the final step of your training.", sourceObjectiveStatus = "unverified-source-field" }
quests[31991] = { id = 31991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Zusshi", description = "I knew you would return to face me once more. Let us see who is truly wiser in the ways of battle.", sourceObjective = "Defeat Seeker Zusshi in a pet battle.", progress = "Despite my wisdom, you manage to surprise me.", completion = "You are indeed superior. If you would pardon me, I must consult the lake for guidance in my defeat.", sourceObjectiveStatus = "unverified-source-field" }
quests[31998] = { id = 31998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Sha of Doubt", description = "{name}, I need you to assemble a hearty group and lead them into the Temple of the Jade Serpent. Activate the Challenger's Orb therein, and vanquish the Sha of Doubt.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", sourceObjective = "Complete the Temple of the Jade Serpent Challenge Mode.", completion = "You have my gratitude, {name}. You've displayed great valor today, and the speed at which you completed the challenge surely will impress your friends and intimidate your foes.", sourceObjectiveStatus = "unverified-source-field" }
quests[31999] = { id = 31999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazgrim's Command", description = "You have a comfortable base of operations, no Alliance around for miles, and a few Horde veterans by your side. It looks like it's time to start painting this continent red.\n\nGeneral Nazgrim should know where to start.", sourceObjective = "Report to General Nazgrim at Strongarm Airstrip in the Jade Forest.", completion = "We may have won the battle against the Alliance, but we won't get any further with this many jabbering monkeys on our perimeter.\n\nThe hozen are our next target.", sourceObjectiveStatus = "unverified-source-field" }
quests[32000] = { id = 32000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Yan-zhu the Uncasked", description = "{name}, I need you to assemble a hearty group and lead them into Stormstout Brewery. Activate the Challenger's Orb therein, and evaporate Yan-zhu the Uncasked.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", sourceObjective = "Complete the Stormstout Brewery Challenge Mode.", completion = "You have my sincerest thanks, {name}. Without fine Stormstout brews to lighten the drudgery of the day, the world would be a dull place indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[32001] = { id = 32001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Sha of Hatred", description = "{name}, I need you to assemble a tranquil group and lead them into the Shado-Pan Monastery. Activate the Challenger's Orb therein, and rescue Taran Zhu from the Sha of Hatred.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", sourceObjective = "Complete the Shado-Pan Monastery Challenge Mode.", completion = "Many blessings upon you, {name}. Driving hatred from this world so quickly deserves rich reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[32002] = { id = 32002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Xin the Weaponmaster", description = "{name}, I need you to assemble a nimble group and lead them into Mogu'shan Palace. Activate the Challenger's Orb therein, and put an end to Xin the Weaponmaster.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", sourceObjective = "Complete the Mogu'shan Palace Challenge Mode.", completion = "Many thanks, {name}. Your martial prowess is second to none, and your alacrity is sure to strike fear in the hearts of your enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[32003] = { id = 32003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Raigonn", description = "{name}, I need you to assemble a cracking group and lead them into the Gate of the Setting Sun. Activate the Challenger's Orb therein and lay waste to Raigonn.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", sourceObjective = "Complete the Gate of the Setting Sun Challenge Mode.", completion = "That was a blow well struck, {name}. I've never seen a {class} fell a giant with such speed.", sourceObjectiveStatus = "unverified-source-field" }
quests[32004] = { id = 32004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Wing Leader Ner'onok", description = "{name}, I need you to assemble an eagle-eyed group and lead them into the Siege of Niuzao Temple. Activate the Challenger's Orb and ground Wing Leader Ner'onok.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", sourceObjective = "Complete the Siege of Niuzao Temple Challenge Mode.", completion = "{name}, that was amazing. Ner'onok is a master tactician, and you schooled him handily.", sourceObjectiveStatus = "unverified-source-field" }
quests[32005] = { id = 32005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Durand", description = "{name}, I need you to assemble a stout group and lead them into Scarlet Monastery. Activate the Challenger's Orb therein, and smite Durand with righteous fury.\n\nReturn to me when you've completed this challenge, and I shall reward you handsomely.", sourceObjective = "Complete the Scarlet Monastery Challenge Mode.", completion = "{name}, you're a stalwart {class}. Your friends and guild mates will surely notice the speed and ferocity with which you conquered the Scarlet Monastery.", sourceObjectiveStatus = "unverified-source-field" }
quests[32006] = { id = 32006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Flameweaver Koegler", description = "{name}, I need you to assemble a cunning group and venture forth into the depths of Scarlet Halls. Activate the Challenger's Orb therein, and put a stop to Flameweaver Koegler's book-burning ways.", sourceObjective = "Complete the Scarlet Halls Challenge Mode.", completion = "Excellent work, {name}. Just the thought of him burning up that beautiful library makes me shudder. Your friends will appreciate the speed with which you dispatched him.", sourceObjectiveStatus = "unverified-source-field" }
quests[32007] = { id = 32007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Darkmaster Gandling", description = "{name}, I need you to assemble a fearless group and lead them into the depths of Scholomance. Activate the Challenger's Orb, and cleanse Scholomance of Darkmaster Gandling's evil presence.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", sourceObjective = "Complete the Scholomance Challenge Mode.", completion = "{name}, you've done a great service. May the skeletons of the dead remain peaceful now that Gandling no longer seeks to disturb their slumber.", sourceObjectiveStatus = "unverified-source-field" }
quests[32008] = { id = 32008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audrey Burnhep", description = "Greetings, {name}! My name is Audrey Burnhep. I've been hearing quite a lot about you recently. You're becoming quite the tamer!\n\nYou should come speak with me in Stormwind. I have connections with some of the finest tamers in all of Azeroth, and I can help you grow even more!", sourceObjective = "Report to Audrey Burnhep in Stormwind.", completion = "Ah, you're {name}. Splendid! Let's get to work then, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[32009] = { id = 32009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Lok'tar, {name}. My name is Varzok. I have heard much your accomplishments as a tamer recently, and I would like to introduce you to trainers around Azeroth so that you may further hone your skills.\n\nPlease speak with me in Orgrimmar so that we may begin.", sourceObjective = "Report to Varzok in Orgrimmar.", completion = "You must be {name}. Well met. I am Varzok.\n\nI will serve as your contact from here on out.", sourceObjectiveStatus = "unverified-source-field" }
quests[32010] = { id = 32010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Celestial Task", description = "Are you familiar with the August Celestials? Yu'lon, Chi-Ji, Xuen, and Niuzao watch over the four corners of Pandaria.\n\nThey watch you as well.\n\nTheir knowledge is most ancient, and most powerful. To those they favor, they can bestow enormous power.\n\nYou may seek to earn their trust, but they need you for a more important task.\n\nThe Vale of Eternal Blossoms is in danger. First, we must all defend the Vale. Then, we can turn our eyes to the Celestials themselves.", sourceObjective = "Earned Revered standing with the Golden Lotus.", sourceObjectiveStatus = "unverified-source-field" }
quests[32011] = { id = 32011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Celestial Task", description = "Are you familiar with the August Celestials? Yu'lon, Chi-Ji, Xuen, and Niuzao watch over the four corners of Pandaria.\n\nThey watch you as well.\n\nTheir knowledge is most ancient, and most powerful. To those they favor, they can bestow enormous power.\n\nYou may seek to earn their trust, but they need you for a more important task.\n\nThe Vale of Eternal Blossoms is in danger. First, we must all defend the Vale. Then, we can turn our eyes to the Celestials themselves.", sourceObjective = "Earned Revered standing with the Golden Lotus.", sourceObjectiveStatus = "unverified-source-field" }
quests[32016] = { id = 32016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Charms of Good Fortune", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With an Elder Charm of Good Fortune, valuable artifacts will find their way into your hands more frequently.", sourceObjective = "Collect 50 Lesser Charms of Good Fortune.", progress = "May these charms bring you great luck, {name}.", completion = "May the stars smile upon you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32017] = { id = 32017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Charms of Good Fortune", description = "Greetings, {name}. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With an Elder Charm of Good Fortune, valuable artifacts will find their way into your hands more frequently.", sourceObjective = "Collect 50 Lesser Charms of Good Fortune.", progress = "May these charms bring you great luck, {name}.", completion = "May the stars smile upon you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32018] = { id = 32018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "His Name Was... Stormstout", description = "An unusual pandaren came through town a few days back. He told a better tale than Pan, drank twice as much as Lee, and then beat me up in front of the bar. All while his little niece made fun of us.\n\nIt was awesome.\n\nThey said they were headed to the Valley of the Four Winds. You should meet him! Just... watch out for that right hook.", sourceObjective = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds.", completion = "Ha ha! You were sent by Bolo? The \"Keg Mender,\" right? From the Drunken Hozen?\n\nHow is his eye healing? Is his friend still hung over?\n\nAhh... that was an enjoyable evening.", sourceObjectiveStatus = "unverified-source-field" }
quests[32019] = { id = 32019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Him... Stormstout", description = "Things were not always like this, {race}. Oh no, they were much, much worse. Not three weeks ago, we were under siege by saurok bandits. They stole our jade, befouled our food stores, and terrorized our cubs.\n\nWe needed a hero, and a hero arrived.\n\nHe drove back their forces, defeated their leader, and returned our stolen jade. All he asked in return was a serpent ride for his niece.\n\nI was never able to thank him. If you are headed to the Valley of the Four Winds, would you relay our thanks?", sourceObjective = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds.", completion = "You come from the Temple of the Jade Serpent? Rain-Zhu sends his thanks?\n\nAi yah... really, that was nothing. I could have defeated that saurok without spilling my beer.\n\nIn fact, I believe I did.", sourceObjectiveStatus = "unverified-source-field" }
quests[32020] = { id = 32020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
