quests[32029] = { id = 32029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[32030] = { id = 32030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once in a Hundred Lifetimes", description = "The time has come, wakener.\n\nThe council's power will combine to bring an end to the corrupted empress.\n\nThis ritual has not been witnessed in one hundred of your kind's lifetimes - and never by an outsider.\n\nIn exchange for your deeds on our behalf, I invite you to behold this great moment in our history.", sourceObjective = "Speak to Klaxxi'va Ik in Klaxxi'vess", completion = "Your arrival is timely, wakener.\n\nOur ritual is underway.", sourceObjectiveStatus = "unverified-source-field" }
quests[32031] = { id = 32031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
