quests[32034] = { id = 32034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[32035] = { id = 32035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got Silk?", description = "Strange noises comin' from over at the Silken Fields.\n\nStrange smells, too.\n\nAlmost makes you think that they could use a cash-strapped {class} to complete a few odd jobs for 'em. Make a few pieces of gold.\n\nOr not.", sourceObjective = "Report to Silkmaster Tsai at the Silken Fields in Valley of the Four Winds.", completion = "Greetings, {class}. Welcome to the Silken Fields.", sourceObjectiveStatus = "unverified-source-field" }
quests[32036] = { id = 32036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[32037] = { id = 32037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[32038] = { id = 32038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stag Mastery", description = "I always was a fan of a good stag hunt. Stags are tough, fast, and territorial.\n\nThey may be plant eaters but they can give any hunter a run for his money.\n\nEast of here is a whole mess of Wilderland Stags just waiting for a hunter like yourself to give 'em a good run.\n\nHappy hunting.", sourceObjective = "Kill 10 Wilderland Stags.", progress = "How goes the hunt?", completion = "I haven't seen stag hunting this good since Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[32039] = { id = 32039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
