quests[32044] = { id = 32044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[32045] = { id = 32045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of the Water", description = "We are all children of the water here in the Valley of the Four Winds. It nourishes us, it grows our vegetables, it brings us life.\n\nSome creatures, however, drink too deeply from the water. They grow too large, and must be eliminated before they cause havoc to those around them.\n\nI am but a simple stonecarver. You, on the other hand...", sourceObjective = "Slay Kracor, Thundergill, and Succula.", completion = "Let this be a lesson to you: don't drink too much of the water.\n\nWhy do you think we have such a big brewery?", sourceObjectiveStatus = "unverified-source-field" }
quests[32046] = { id = 32046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
