quests[32097] = { id = 32097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[32105] = { id = 32105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Monument Ledger", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", sourceObjective = "Put the artifact on display.", sourceObjectiveStatus = "unverified-source-field" }
quests[32106] = { id = 32106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift" }
quests[32107] = { id = 32107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Tiger Gourami", description = "You've caught a unique fish... with wings.  Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.", sourceObjective = "Bring the Flying Tiger Gourami to Nat Pagle at Anglers Wharf.", sourceObjectiveStatus = "unverified-source-field" }
quests[32108] = { id = 32108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Domination Point", description = "Now it is time to show this new land the true strength of the Horde.\n\nReturn to the beach and light the remaining signal fire. Our fleet is waiting.", sourceObjective = "Light the Signal Fire on the beach of the Horde Landing Site to signal the Horde fleet.", completion = "<This fire will signal the full might of the Horde invasion fleet to land on this beach, beginning Garrosh's campaign in Pandaria.>", sourceObjectiveStatus = "unverified-source-field" }
quests[32109] = { id = 32109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lion's Landing", description = "For too long the Horde has been allowed to run rampant across Azeroth. I will not see these new lands conquered by some barbaric \"warchief.\"\n\nAre you ready to bring Alliance justice to the shores of Pandaria?\n\nLet us return to the landing site. Use the flare launcher to bring in the fleet proper, and begin Operation: Shieldwall.", sourceObjective = "Use the Flare Launcher in Krasarang Cove to signal the Alliance fleet.", completion = "<Blue sails are barely visible on the horizon - the full might of the Alliance fleet, awaiting one final signal.>", sourceObjectiveStatus = "unverified-source-field" }
quests[32114] = { id = 32114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So, You Wanted to Test Daily Quests?", description = "You wanna test dailies? Well alright then." }
quests[32115] = { id = 32115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shackles of the Past", description = "The mogu are a bunch of right bastards!\n\nThey enslaved the pandaren who worked these caves even after their death. Ye' gotta go free their spirits! It's just not right.\n\nBe careful though... so much trauma, they don't know what's a friend and what's an enemy. So they'll probably fight back.", sourceObjective = "Free 14 Troubled Slave Spirits.", sourceObjectiveStatus = "unverified-source-field" }
quests[32116] = { id = 32116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priorities, People!", description = "When I ordered the excavation of the tunnel to the northwest, I thought we'd find something useful. Gold, iron... anything!\n\nInstead, we found mogu artifacts, and I get a bunch of dwarves from the Explorers' League to baby-sit.\n\nI hear from the soldiers that there's trouble in the mines. I have orders from Wrynn that I have to support the Explorers' League, but I can't spare any troops. Can you get down there and find out what's going on?", sourceObjective = "Meet with Hilda Hornswaggle at the Ruins of Ogudei in Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32118] = { id = 32118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Advantage", description = "The fools in the Explorers' League have excavated an ancient mogu ruin to the northeast. And - of course - in their bumbling, they've disturbed the mogu spirits within.\n\nWe are going to take advantage of their ineptitude. Take this portal and meet with Kaelis Sunsoar, my contact within the ruins.", sourceObjective = "Use the portal at Sparkrocket Outpost to meet with Kaelis Sunsoar at the Ruins of Ogudei in Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32119] = { id = 32119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Is A Mystery", description = "There's somethin' down there that was spookin' the workers. Some kind o' anomaly... looks like a ghost, or a magic spell... like nothing I've ever seen.\n\nI did manage to get a reading on it and put together this device to try to track it down. The display on the device will let you know roughly how close you are. \n\nOnce you get close enough, you can use it to draw out the anomaly and get rid of it for good!", sourceObjective = "Use Hilda's Anomaly Tracker to find and disperse an anomaly.", sourceObjectiveStatus = "unverified-source-field" }
quests[32120] = { id = 32120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of Ogudei", description = "The ruins which we are occupying were built by Ogudei - an ancient mogu ruler. We know little about who he was, though the rise of the spirits in this area seems to indicate that it was related to spirit binding.\n\nWhen you destroy these spirits, a small amount of their essence will remain in this world. Bring it to us - we will analyze it and hopefully learn more about Ogudei's history - and his power.", sourceObjective = "Collect 5 Ancient Mogu Essence.", sourceObjectiveStatus = "unverified-source-field" }
quests[32121] = { id = 32121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirit Trap", description = "In the ruins there are a bunch of right nasty blue crystals. Look at 'em the wrong way and bloody angry ghosts run out at ya.\n\nI'm gonna be needing ye' to go in and clear some of them out so we can get our people back to work.", sourceObjective = "Destroy 3 Spirit Traps.", sourceObjectiveStatus = "unverified-source-field" }
quests[32122] = { id = 32122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogudei's Lieutenants", description = "When we dug through to an ancient section of the mogu ruins, that's when all this nasty business went down - and that's where the two worst o' these ghosties emerged.\n\nWe need them gone, friend.", sourceObjective = "Kill Meng-do, Strength of Mountains, and Gen-li, Twister of Words.", sourceObjectiveStatus = "unverified-source-field" }
quests[32123] = { id = 32123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death on Two Legs", description = "The Alliance has made landfall. If we do not defeat them here, any hope of a Horde presence on this continent is lost.\n\nGo to the battlefield south of here and slay Alliance you find.\n\nShow them how any Horde who still stands on two legs will be the death of ten Alliance!", sourceObjective = "Defeat 10 Alliance soldiers in Domination Point.", progress = "The Alliance must find no purchase on these shores.", completion = "Well done, {name}. I see your time in this land has hardened your resolve and sharpened your skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[32126] = { id = 32126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tear It Up", description = "The Alliance may be cowardly, but they are not fools. Their assault would be formidable, if it were directed at lesser creatures.\n\nTo sustain a siege and put pressure on our troops they are air dropping in supplies to support their ground forces.\n\nSearch the beaches and docks to the south for any airdropped supplies and smash them.\n\nLet the Alliance see their food and ammunition destroyed before their eyes and despair.", sourceObjective = "Destroy 8 Alliance Supply Drops.", completion = "Just remember, the weapon of choice is not always the weapon with the longest range or heaviest amount of damage. In the end, the best weapon is the weapon that works every time.", sourceObjectiveStatus = "unverified-source-field" }
quests[32127] = { id = 32127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Dead, All Dead", description = "Our Warchief has dispatched me to these shores to deal with this pitiful Alliance threat.\n\nThese humans and their allies have proven to be very dependent on their leaders. No initiative of their own.\n\nAs you walk the battlefield today look to the Alliance ships off our southern shores. Find their captains.\n\nSlay them.\n\nFor the Horde!", sourceObjective = "Defeat Captain Brent the Black and Captain Mulkey.", progress = "Every weapon has its function.", completion = "It is not enough to rob the Alliance of their leaders. We must warn those who would aspire to leadership the cost of such ambition.", sourceObjectiveStatus = "unverified-source-field" }
quests[32128] = { id = 32128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another One Bites the Dust", description = "The Alliance have planted themselves off our southern coast and continue to pepper our ground forces with cannon fire. Let us see how great their siege is without such support.\n\nBoard the enemy vessels and destroy their reserve ammunition. This will take the teeth out of their bite.", sourceObjective = "Detonate the explosive cargo of The Defiant and Valor's Edge.", completion = "Ah! Look at them burn. These new Alliance craft require more to destroy them permanently however. I am sure they will have those fires out in a day or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[32129] = { id = 32129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defense Daily 06" }
quests[32130] = { id = 32130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Luck, Have Fun", description = "I've got some customers lined up that wanna collect some good old fashioned ears. But not any old ears. They only want the absolute waxiest ears money can buy! \n\nGuess they think they're lucky or something'.\n\nAnyways, I need you to go get 'em for me. I don't want to hurt any animals, so you'll need to get 'em from the Alliance over at Lion's Landing.\n\nHave fun - and remember, only bring me the waxiest!", sourceObjective = "Collect 10 Extra-Waxy Alliance Ears at Lion's Landing in Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32131] = { id = 32131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Require More Minerals!", description = "Gnomes are excavating a stone quarry to the northeast.\n\nThey're building stuff with it!\n\n<Zazzix rolls his eyes.>\n\nThey're too stupid to realize it's special mogu stone for creating animated statues. \n\nWE can mix with a little Goblin magic juice to make some real big explosions!\n\nBut the stuff is heavy. They've got some of their stupid bomb-bots there for excavating the stone. Blow 'em up near slabs and you'll get chunks small enough to carry. \n\nOr, just kill 'em and take it. Whatever works.", sourceObjective = "Collect 20 Animatable Stone chunks from the Lion's Landing quarry. Lion's Landing Engineers carry them, or you can destroy stone slabs with collateral damage to blow them into chunks you can carry.", sourceObjectiveStatus = "unverified-source-field" }
quests[32132] = { id = 32132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worker Harassment", description = "Our goblin friends do not have the grasp of strategy necessary to win a long term engagement, I'm afraid.\n\nThe key to eliminating any permanent establishment is to attack their ability to replenish their troops and to rebuild.\n\nIn this case, that means taking out their Peasants. Kill them, and you weaken the foundation. The rest of the keep is bound to crumble.", sourceObjective = "Kill 30 Lion's Landing Peasants.", sourceObjectiveStatus = "unverified-source-field" }
quests[32133] = { id = 32133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sentry Wards", description = "We've spotted heavy air support over their base, in the form of way too many dwarves on way too many griffons. Means we can't get any vision of the area from above.\n\nA troll... friend of mine gave us a set of Sentry Wards, which we can use to spy on their base and get a vantage point on what's going on in there.\n\nBad news, friend - you're going to be the one going in there.", sourceObjective = "Place Sentry Wards on the Docks, in the Town Hall, and on the Second Floor of the Barracks at Lion's Landing.", sourceObjectiveStatus = "unverified-source-field" }
quests[32134] = { id = 32134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard Counter", description = "We've managed to get some Demolishers on the beach, but the stupid dwarves are also out there with their stupid mortar tubes, preventing the Demolishers from pushing forward and assaulting the keep itself!\n\nGet out there, kill some dwarves, and blow up some mortar tubes.", sourceObjective = "Kill 8 Lion's Landing Mortar Team Engineers and destroy 2 Lion's Landing Mortar Tubes.", sourceObjectiveStatus = "unverified-source-field" }
quests[32135] = { id = 32135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero Killer", description = "There are some situations in which taking out one of their soldiers is more important than killing hundreds.\n\nThey've deployed some of their heroes to the battlefield to help rally their defenders. Not only will killing them soften their defense, it will also leave their morale crippled.\n\nSo go, take one down for me. You can handle it.", sourceObjective = "Kill an Alliance Hero at Lion's Landing in Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32138] = { id = 32138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Lumber", description = "Everyday it's the same thing! \"We're out of this!\", \"We need more of that!\", \"Why don't you ever do anything?!\"\n\nI work! I do things! They can be so hurtful! I'm doin' my best down here!\n\nOh yeah, we need more lumber! Go down and tell that good for nothin' Zino to get his shredders in gear!", sourceObjective = "Find Zino \"The Shredder\" Quickchop in the Lumber Farm.", sourceObjectiveStatus = "unverified-source-field" }
quests[32139] = { id = 32139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stacked!", description = "We just filled an order this morning. How could they possibly need more already?!\n\nMy team has been workin' double-time to get these trees chopped and processed.\n\nProblem is we have an infestation of Lion's Landing troops down here. I already risked my neck once today, I'm not goin' back out there!\n\nGoob will go with you and help you fill this order. He's not the brightest, but he can do the heavy liftin'.", sourceObjective = "Gather 9 Pieces of Domination Point Lumber from the Lumber Farm.", sourceObjectiveStatus = "unverified-source-field" }
quests[32140] = { id = 32140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Iron", description = "When they said they found some amazing rocks in that mine I envisioned diamonds. Everyone knows all mines have diamonds, silly! At the very least rubies!\n\nInstead, all I got was this strange iron! What am I supposed to do with this?\n\nOh well, no one said this job would be glamorous. I just do what I can to add a little class.\n\nWe just got another work order for iron. Go see Daxil down near Oregrind's Dig and get it filled pronto!", sourceObjective = "Find Daxil \"The Gem\" Oregrind near Oregrind's Dig.", completion = "Is she still complaining about diamonds and rubies? We found something better than diamonds down here!\n\nThis ore is special. It has power!", sourceObjectiveStatus = "unverified-source-field" }
quests[32141] = { id = 32141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Metal", description = "<Daxil narrows her eyes and speaks in a hushed tone.>\n\nSometimes we dig too deep, {class}. Sometimes, we uncover something so horrible we wish we hadn't started diggin'...\n\nJust kidding! I mean, don't get me wrong, we did find something unexpected. The ore we're finding down there is not your average run-of-the-mill iron.\n\nThere is just one problem; Shale Spiders! We're struggling to keep these orders filled.\n\nMaybe you can lend us a hand?", sourceObjective = "Obtain 7 chunks of Energized Ore from Oregrind's Dig.", progress = "Did you happen to find anything sparkly while you were down there?", completion = "Did they manage to find anything useful down there? Maybe an emerald or an opal? Is it too much to ask for a little bit of effort?!\n\nNevermind! I'll make sure this shipment gets where it's goin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[32142] = { id = 32142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Will Rock You", sourceObjective = "Slay 10 Orcs at Domination Point.", progress = "Glory to the Alliance.", completion = "Well done, soldier. That should help keep the horde in check.", sourceObjectiveStatus = "unverified-source-field" }
quests[32143] = { id = 32143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Kind of Magic", sourceObjective = "Find the three Scout-o-Matics in Domination Point.", sourceObjectiveStatus = "unverified-source-field" }
quests[32144] = { id = 32144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Pressure", description = "The Horde are consumed by pride and will fight to the death without a second thought.\n\nWe need to find a way to break their will that does not involve massive loss of our numbers.\n\nLook for the Horde supplies along the coastline and near their ships. Smash their supplies.\n\nNothing breaks the will of a defender like seeing their hope of food go up in a puff of smoke.\n\nWhen you are done, find Sully behind enemy lines. He has the next task for you.", sourceObjective = "Destroy 8 Horde Supply Crates.", completion = "Thanks to your actions, the Horde knows it cannot feed its troops.\n\nThe timeframe they can withstand a siege is greatly reduced and their morale is going to start suffering soon.\n\nWe just need to keep applying pressure.", sourceObjectiveStatus = "unverified-source-field" }
quests[32145] = { id = 32145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Lose Your Head", description = "My probes have detected three very dangerous targets in the courtyard of Domination Keep.\n\nThey have an ogre emissary, a Kor'kron officer, and an insane goblin bomb maker.\n\nMy siege-o-matics are not ready for one on one combat so it is up to you to eliminate the targets.\n\nGood luck! Report back to me on the Skyfire when done.", sourceObjective = "Defeat Stone Guard Ruk'ra, Bombgineer Snicklefritz, and Or'Dac.", completion = "Great work! Sorry to put good soldiers in harms way but my Auto-Demolish-o-Tronic Mk 2 isn't functional yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[32146] = { id = 32146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer to Fall", description = "It looks like the Horde thinks they can hide behind their heavy hitting mooks.\n\nThe mooks are tough, powerful, and dumber than an ogre with a hangover.\n\nGo down there and bring the hammer of the Alliance fury down on them!", sourceObjective = "Kill 5 Heavy Mooks.", completion = "Thank you soldier. That should teach the Horde that it will take more than a couple of mooks to scare us away.", sourceObjectiveStatus = "unverified-source-field" }
quests[32147] = { id = 32147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack Daily 06" }
quests[32148] = { id = 32148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack! Move!", description = "Sure, they've got about plenty of grunts out there, pounding on our door, waiting to cut our heads off.\n\nI'm not worried about grunts. But they've got shamans and raiders, too. The shamans use their magic to empower the grunts, and the raiders are fast and specialize in taking out our buildings.\n\nI need you to get out there and kill some of those shamans and raiders.\n\nGo! Attack! Move!", sourceObjective = "Kill 12 Dominance Shamans or Dominance Raiders.", sourceObjectiveStatus = "unverified-source-field" }
quests[32149] = { id = 32149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resource Gathering", description = "Oh, the poor peasants...\n\nThey are cowards, yes, of course. But they don't know how to fight, and they go out to collect lumber for our efforts... the Horde targets them... It's just awful all around!\n\nBut, we need that lumber if we're going to hold out. Go out and collect any they've dropped.", sourceObjective = "Collect 12 Lion's Landing Lumber by recovering it from piles of Hastily Abandoned Lumber.", sourceObjectiveStatus = "unverified-source-field" }
quests[32150] = { id = 32150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Block", description = "The Horde decided to put goblins in charge of their logistics. And where you have goblins, you have carelessly placed explosives.\n\nScouts have reported that they have their supplies in carts that also contain demolisher ammunition. Look at those crates the wrong way, and they'll blow sky high. \n\nWith enough Horde resources destroyed, we'll put a time limit on their attack and save lives. So go and take out those carts!", sourceObjective = "Destroy 8 Domination Point Supply Carts.", sourceObjectiveStatus = "unverified-source-field" }
quests[32151] = { id = 32151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tower Defense", description = "The gnomes are running our quarry operation to the northwest. The stone there is especially tough - the gnomes tell me the mogu used it to fashion their constructs. \n\nI don't know. What I do know is that we use that stone to build our towers, and the Horde has dispatched the Bilgewater goblins to steal it from us.\n\nGet out there and get some back. By the way - collateral damage may break up the stone slabs there. If so, pick that up, too.", sourceObjective = "Collect 20 Animatable Stone at the Lion's Landing Quarry from Bilgewater Goblins or by destroying stone slabs there with collateral damage.", sourceObjectiveStatus = "unverified-source-field" }
quests[32152] = { id = 32152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege Damage", description = "The Horde got the bright idea to send Bilgewater goblins to attack our quarry.\n\nThey've been packing heavy explosives - heavy explosives that will react with the ammunition in their demolishers.\n\nKill the Bilgewater goblins until you find an explosive, plant it on one of the demolishers... and BOOM! Siege ended.", sourceObjective = "Find a Bilgewater Blasting Cap on a Bilgewater Sapper, and then plant it on a Domination Point Demolisher.", sourceObjectiveStatus = "unverified-source-field" }
quests[32153] = { id = 32153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero Killer", description = "Look, you're tough. Tougher than the rest of the men and women I've got here. Which means I need you for a special mission.\n\nThe Horde is throwing their best against us. Heroes of their armies - Blademasters, Tauren Chieftans, you name it.\n\nI need you to go take one out. It'll be a huge blow, not just to their offensive but also to morale.", sourceObjective = "Kill a Horde Hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[32154] = { id = 32154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn Out!", description = "Those goblins are gettin' out of hand! First they level the forest and set up that abomination of a rig. Then, they start dumpin' their oil barrels into the bay!\n\nWe got to put a stop to this madness! At the very least we need ta set them back.\n\nWe need to take out their fuel supply! Maybe you'll even get to kill a few goblins in the process!", sourceObjective = "Use the Unstable Explosive to destroy the Northestern Fuel Tank, Northern Fuel Tank, and the Northwestern Fuel Tank.", completion = "Wish I could've been there to watch their fuel burn! Probably put on quite the show.\n\nYou've done well, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[32156] = { id = 32156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Only Right", description = "This is barbaric warfare, {class}! We've lost so many trying to keep the Bilgewater operation from spreading any further.\n\nThose fallen soldiers fought honorably and deserved to be given their last rights. At the very least we need to be able to notify their next of kin.\n\nPerhaps you can collect their identification tags so we can honor them in some small way.", sourceObjective = "Retrieve 7 Shieldwall Soldier Dog Tags from the Fallen Shieldwall Soldiers in and around Bilgewater Beach.", progress = "Even warfare should have some courtesies.", completion = "You have done these soldiers a great service, {name}. The only thing left to do is make sure they did not die in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[32157] = { id = 32157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Good Goblin...", description = "The destruction in Krasarang is unforgivable, {class}. The only way to put an end to this is to destroy the Bilgewater operation.\n\nThis is for the greater good of Pandaria and the Alliance. Go to Bilgewater Beach and cut them down! No doubt the Horde will come to their assistance.\n\nDestroy them!", sourceObjective = "Kill 10 Bilgewater Goblins in and around Bilgewater Beach.", completion = "Excellent work, {class}! Eventually we will wipe the Horde from this continent.", sourceObjectiveStatus = "unverified-source-field" }
quests[32158] = { id = 32158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two Step Program", description = "Shredmaster Packle is responsible for much of the devastation down there, {class}.\n\nRumor has it he modified the shredders to work more quickly with less regard for the collateral damage they can inflict.\n\nImagine the agony the trees must endure being hacked at. It will be difficult to recover from this level of destruction.\n\nThe first step in any recovery is acknowledging the problem. Step two is eliminating that problem.", sourceObjective = "Destroy Shredmaster Packle in Quickchop's Lumber Farm.", completion = "Excellent work, {name}! Now the forest can begin its regrowth process. From all death comes new life, and a new opportunity to protect it.", sourceObjectiveStatus = "unverified-source-field" }
quests[32161] = { id = 32161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Hunt: The Crane", description = "Along with the snare, you get some advice on crane hunting:\n\nThe greatest cranes of the Krasarang Wilds are not tempted by simple things like food. You will need to play on the creatures' emotions if you wish to draw them from their hiding places in the jungle.\n\nCranes abound on both the Cradle of Chi-ji and the Narsong Spires, both of which can be found east of here. Pluck those cranes' quills, then place them in a visible spot near the Crane Temple. Your quarry will come running to you.", sourceObjective = "Obtain 5 Pristine Golden Crownfeathers and a Pristine Jet Crownfeather.", progress = "This is the spot, near the Crane Temple.", completion = "You place the feathers in the dirt, then look off in the direction of the temple...", sourceObjectiveStatus = "unverified-source-field" }
quests[32162] = { id = 32162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Hunt: The Tiger", description = "Along with the trap, you get some advice on tiger hunting:\n\nTigers are gluttonous creatures, and large game is hard to come by in this jungle. If you wish to tempt the most elder cats out of their hiding places, you may do so with a meal.\n\nJust on the other side of the Serpent's Spine, you will find a herd of yaks. Slay them, bring their meat to the jungle's edge, set up your trap, and wait.", sourceObjective = "Obtain 25 Unbruised Yak Haunches.", progress = "This looks like an ideal spot for a tiger trap.", completion = "You lay the meat out atop the trap, then turn your eyes toward the jungle...", sourceObjectiveStatus = "unverified-source-field" }
quests[32163] = { id = 32163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Hunt: The Crab", description = "Along with the crate, you get some advice on crab hunting:\n\nCrabs are strange, primordial creatures, with wildly different motivations than you or I.\n\nSmall crabs are easy to find and hunt, but the large ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell.\n\nThe Unga villagers to the southeast allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.", sourceObjective = "Obtain 30 Funky Rotten Fish from Unga Villagers in Unga Ingoo.", progress = "This looks like a good place to catch a crab.", completion = "You spread out the decaying fish, prepare the crate, then turn your eyes toward the beach...", sourceObjectiveStatus = "unverified-source-field" }
quests[32164] = { id = 32164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Hunt: The Crane", description = "Along with the snare, you get some advice on crane hunting:\n\nThe greatest cranes of the Krasarang Wilds don't care about simple things like food. You need to play on the creatures' emotions if you want to draw them out of the jungle.\n\nThere's plenty of cranes on the Cradle of Chi-ji and on the Narsong Spires, both to the west of here. Pluck some of those cranes' quills, then put them in a visible spot near the Crane Temple. Your quarry will come running to you.", sourceObjective = "Obtain 5 Pristine Golden Crownfeathers and a Pristine Jet Crownfeather.", progress = "This is the spot, near the Crane Temple.", completion = "You place the feathers in the dirt, then look off in the direction of the temple...", sourceObjectiveStatus = "unverified-source-field" }
quests[32165] = { id = 32165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Hunt: The Tiger", description = "Along with the trap, you get some advice on tiger hunting:\n\nTigers are gluttons, and big game is hard to come by in this jungle. If you want to tempt the elder cats out of their hiding places, you need a tempting meal.\n\nJust on the other side of the Serpent's Spine, you can find a herd of yaks. Kill them, bring their meat to the jungle's edge, set up your trap, and wait.", sourceObjective = "Obtain 25 Unbruised Yak Haunches.", progress = "This looks like an ideal spot for a tiger trap.", completion = "You lay the meat out atop the trap, then turn your eyes toward the jungle...", sourceObjectiveStatus = "unverified-source-field" }
quests[32166] = { id = 32166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Hunt: The Crab", description = "Along with the crate, you get some advice on crab hunting:\n\nCrabs are strange, old creatures, with different motivations than us.\n\nSmall crabs are easy to find and hunt, but the big ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell.\n\nThe Unga villagers to the southwest allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.", sourceObjective = "Obtain 30 Funky Rotten Fish from Unga Villagers in Unga Ingoo.", progress = "This looks like a good place to catch a crab.", completion = "You spread out the decaying fish, prepare the crate, then turn your eyes toward the beach...", sourceObjectiveStatus = "unverified-source-field" }
quests[32167] = { id = 32167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient's Fall", description = "The crane has fallen.You will learn:", sourceObjective = "Speak with Jorn Skyseer at Domination Point in Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
quests[32168] = { id = 32168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End of an Elder", description = "The tiger has fallen.You will learn:", sourceObjective = "Speak with Jorn Skyseer at Domination Point in Krasarang Wilds.", sourceObjectiveStatus = "unverified-source-field" }
