quests[32175] = { id = 32175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Pet Battle!", description = "Are you prepared to test the mettle of your pets...?", sourceObjective = "Defeat Jeremy Feasel in a pet battle.", progress = "My, my. Well done!", completion = "I must say, good show!", sourceObjectiveStatus = "unverified-source-field" }
quests[32181] = { id = 32181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Crane", description = "The ancient crane is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", sourceObjective = "Bring the Ancient Bloodcrown Crane to Jorn Skyseer.", progress = "Welcome back, {name}.", completion = "It only took one to capture the beast, but it will take many more to truly defeat it.\n\nSpeak to me again when you have gathered enough allies. We shall test the grace of the crane against the might of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32182] = { id = 32182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Tiger", description = "The elder cat is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", sourceObjective = "Bring the Krasari Elder to Jorn Skyseer.", progress = "Welcome back, {name}.", completion = "It only took one to capture the beast, but it will take many more to truly defeat it.\n\nSpeak to me again when you have gathered enough allies. We shall test the ferocity of the tiger against the might of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32183] = { id = 32183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Crab", description = "The colossal crab is alive, but stunned.\n\nYou should bring it back to Jorn Skyseer before it wakes up.", sourceObjective = "Bring the Colossal Viseclaw to Jorn Skyseer.", progress = "Welcome back, {name}.", completion = "It only took one to capture the beast, but it will take many more to truly defeat it.\n\nSpeak to me again when you have gathered enough allies. We shall test the resilience of the crab against the might of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32184] = { id = 32184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Crane", description = "The ancient crane is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", sourceObjective = "Bring the Ancient Bloodcrown Crane to Huntsman Blake.", progress = "Welcome back, {name}.", completion = "It might have taken just one {race} to capture this beast, but it will take many more to put it down.\n\nGather up some friends, then come and speak with me again. We'll pit the grace of the crane against the glory of the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[32185] = { id = 32185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Tiger", description = "The elder cat is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", sourceObjective = "Bring the Krasari Elder to Huntsman Blake.", progress = "Welcome back, {name}.", completion = "It might have taken just one {race} to capture this beast, but it will take many more to put it down.\n\nGather up some friends, then come and speak with me again. We'll pit the power of the tiger against the glory of the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[32186] = { id = 32186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beastmaster's Quarry: The Crab", description = "The colossal crab is alive, but stunned.\n\nYou should bring it back to Huntsman Blake before it wakes up.", sourceObjective = "Bring the Colossal Viseclaw to Huntsman Blake.", progress = "Welcome back, {name}.", completion = "It might have taken just one {race} to capture this beast, but it will take many more to put it down.\n\nGather up some friends, then come and speak with me again. We'll pit the stamina of the crab against the glory of the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[32189] = { id = 32189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shabby New Face", description = "A strange fellow in a pointy hat showed up this morning trying to sell some kinda special seeds. Claimed they were magic.\n\nI welcome a little competition - business is business, after all - but this gentleman had a certain... shabby look to him. Oh, and he stunk somethin' FIERCE.\n\nWould you check up on him, just to make sure he's on the level? He's over there by Jian Ironpaw, making a meal out of the samples.", sourceObjective = "Speak with Barnaby Fletcher in Halfhill Market.", sourceObjectiveStatus = "unverified-source-field" }
quests[32190] = { id = 32190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Mogujia", description = "Throm-ka, {class}. While we were busy defending our foothold here, Regent Lord Lor'themar Theron led a research expedition north into Kun-Lai Summit.\n\nUnfortunately, it seems they have encountered trouble.\n\nWarchief Garrosh Hellscream has already departed to lend his assistance, but he will require additional reinforcements.\n\nGo northward into the mountains of Kun-Lai. Speak to Tak-Tak for transportation.", sourceObjective = "Find Regent Lord Lor'themar Theron at Mogujia. Speak to Tak-Tak at Domination Point for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32191] = { id = 32191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Guardians", description = "Before the mogu overwhelmed our scouting party, we found relics scattered amongst the ruins to the north.\n\nI would like to collect some samples, but the mogu's terracotta watchdogs are too much for us to handle.\n\nIf you could clear the area of their presence, we will be able to resume our work.", sourceObjective = "Kill 5 Korune Guardians.", sourceObjectiveStatus = "unverified-source-field" }
quests[32192] = { id = 32192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodlines", description = "We managed to fend off the mogu wardens and their dogs, but many of the blood elves from the scouting party were not as lucky.\n\nMany of my people are trapped inside the ruins to the north. We are devising a solution to break them out, but I believe there may be a more straightforward approach.\n\nGo to the ruins and kill the wardens guarding each prisoner. If my intuition is correct, this will free our comrades.", sourceObjective = "Free 6 Domination Mages by killing Korune Wardens.", sourceObjectiveStatus = "unverified-source-field" }
quests[32193] = { id = 32193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Mogujia", description = "The Explorer's League sent an expedition north some days ago.\n\nWe haven't heard from them since, and I'd sleep better at night knowing our folks aren't in some sort of trouble.\n\nLast I heard, Brann Bronzebeard was heading toward Mogujia in the Kun-Lai Summit.\n\nFind him and report back with their status. Fennie over there can give you a ride if you need one.", sourceObjective = "Find Brann Bronzebeard at Mogujia. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32194] = { id = 32194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Blood", description = "The Explorer's League is here to excavate the ruins, and it's my job to protect them.\n\nWhen we arrived, we found this place crawling with blood elves. Apparently,the Horde are just as interested in the mogu as we are.\n\nThis gives quite an opportunity to thin our enemies' numbers, and steal their findings, too.\n\nSlay any blood elves you find in the ruins, and bring back whatever they are digging up.", sourceObjective = "Collect 5 Korune Artifacts from Silvermoon Runeseekers, Dominance Mages, or Dominance Knights.", sourceObjectiveStatus = "unverified-source-field" }
quests[32195] = { id = 32195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anger Remains", description = "From the looks o' our initial survey, this entire area is humming with residual sha energy.\n\nYou know what ta do, {name}. Destroy any last traces ye can find o' the stuff!", sourceObjective = "Kill 27 Angerlings.", sourceObjectiveStatus = "unverified-source-field" }
quests[32197] = { id = 32197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Meatloaf", description = "We've been gettin' complaints right and left that the Boss-Lady gets all the good grub and leaves the scraps for the others.\n\nBetween you and I, they may be onto somethin' here. I don't even get to eat as good as she does!\n\nWe need somethin' Sezik can make a lot of that at least attempts to disguise how inedible the food is here...\n\nI got it! Mystery Meatloaf!", sourceObjective = "Obtain 7 Chunks of Mystery Meat from the local wildlife.", progress = "What do ya got for me now?", completion = "I have standards ya know! I'm a chef, not a magician!\n\nThe only mystery here is how Duke thinks he'll pull this over on everyone else!", sourceObjectiveStatus = "unverified-source-field" }
quests[32198] = { id = 32198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Magical, Flying Kingdom's Trash...", description = "Before we enter into a business relationship, I am required by the terms of my rehabilitation program to inform you that I am a recovering potion addict.\n\nThere, now that THAT's out of the way, let's talk portals!\n\nYou see, the big portals in the cities - the ones running all day and night - leak tons of magical energy. It crystallizes around the edges and is generally regarded as trash.\n\nBut I noticed during my, uh... hiatus in the sewers of Dalaran, that these shards still had power.\n\nInterested?", sourceObjective = "Speak with Barnaby Fletcher to learn more about Portal Shards.", sourceObjectiveStatus = "unverified-source-field" }
quests[32199] = { id = 32199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasarang Steampot", description = "The Boss-Lady desires crabs!\n\nWhy are you looking at me like that? It's not uncommon for a classy person, such as her loveliness, to want crab for dinner. What did you think I meant?\n\nThere are some big crabs wandering around on Bilgewater Beach that should be suitable for her refined palate.\n\nBring Sezik the best crab meat you can find!", sourceObjective = "Obtain 5 chunks of Polluted Viseclaw Meat from the Viseclaw crabs on Bilgewater Beach.", sourceObjectiveStatus = "unverified-source-field" }
quests[32200] = { id = 32200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangers of Za'Tual", description = "{name}, what I ask of you is little short of genocide, but it is a task that must be done.\n\nFind trolls within their town or on the beach and slay them, for the good of us all.", sourceObjective = "Slay 12 Trolls in Za'Tual.", sourceObjectiveStatus = "unverified-source-field" }
quests[32201] = { id = 32201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grave Circumstances", description = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder.\n\nIf our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position.\n\nThey must be eliminated.", sourceObjective = "Kill 10 Shan'ze Gravekeepers, Shan'ze Soulrippers, or Shan'ze Thundercallers.", sourceObjectiveStatus = "unverified-source-field" }
quests[32204] = { id = 32204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skumblade Threat", description = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations.\n\nThin their numbers, {name}. Once the Horde takes full control of this island, we can look for more permanent solutions.", sourceObjective = "Slay 10 Skumblade saurok.", sourceObjectiveStatus = "unverified-source-field" }
quests[32206] = { id = 32206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Just Won't Do", description = "The Zandalari here are very powerful, {class}. They should not be underestimated. We cannot afford to ignore them as a threat simply because they do not wield swords.\n\nMore arrive every day, and with them centuries of magic knowledge. This threat must be dealt with, and quickly.\n\nAid us in clearing this area, {class}. Perhaps we can even learn something from them in the process.", sourceObjective = "Kill any 8 Zandalari trolls within Conqueror's Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[32207] = { id = 32207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saur Loser", description = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry.\n\nWe need you to kill any Zandalari you find in there before they can get their mounted monstrosities out into the open battlefield.", sourceObjective = "Defeat 10 Zandalari trolls in the Beast Pens.", sourceObjectiveStatus = "unverified-source-field" }
quests[32208] = { id = 32208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximum Capacitor", description = "The mines north of here are being used to extract Ghost Iron ore and energize it with lightning energy.\n\nWe need to destroy the drills they use to extract the ore. They are impervious to normal attack, but can be overloaded using the proper methods.\n\nOh - and while you're there, take out whoever is running the operation.", sourceObjective = "Interact with the three lightning drills in the Ghost Iron Mines to destroy them, and kill Metal Lord Mono-Han.", sourceObjectiveStatus = "unverified-source-field" }
quests[32210] = { id = 32210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill mogu boss for key, use object behind jumping puzzle" }
quests[32212] = { id = 32212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assault on Zeb'tula", description = "Our scouting efforts along the coast have given us valuable intelligence about the island, {class}.\n\nHowever, we will accomplish nothing if we do not advance forward onto the mainland.\n\nI have assembled a team of our most elite aerial units to begin the attack.\n\nI would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment.\n\nWhen you are ready to begin the attack, speak to me.", sourceObjective = "Complete the Assault on Zeb'tula. Speak to Lor'themar Theron to begin the attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[32215] = { id = 32215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heinous Sacrifice", description = "The Zandalari perform heinous rites against our people! They must be stopped!\n\nDelve into the heart of the Za'Tual and destroy their altars.", sourceObjective = "Destroy the Zandalari sacrificial altars.", sourceObjectiveStatus = "unverified-source-field" }
quests[32217] = { id = 32217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Offerings", description = "The spirtibinders of the Zandalari perform sacrificial rites to appease the loa and their vile gods. These dark rituals involve the sacrifice of our people.\n\nDestroy any offerings you can find among their tents in Za'Tual and perhaps we can stall the sacrifices.", sourceObjective = "Destroy 6 Zandalari Offerings.", sourceObjectiveStatus = "unverified-source-field" }
quests[32218] = { id = 32218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of the Enemy", description = "The mogu here at the Court of Bones are bolstering their army by resurrecting the spirits of their dead.\n\nWe cannot allow them to revive their fallen warriors.\n\nTake this torch and burn any mummified corpses that you can find.\n\nWe will destroy our enemies before they have a chance to rise.", sourceObjective = "Burn 8 Mummified Remains.", sourceObjectiveStatus = "unverified-source-field" }
quests[32220] = { id = 32220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Surrender", description = "We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals.\n\nThe mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war.\n\nHorde or Alliance, it matters not. We cannot allow the mogu to bolster their numbers.\n\nGo into the crypts. Free any prisoners that are still living.", sourceObjective = "Save 6 Sunreaver Scouts or Silver Covenant Scouts.", sourceObjectiveStatus = "unverified-source-field" }
quests[32221] = { id = 32221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Beach", description = "Our lumber supply is being jeopardized by constant attacks from Lion's Landing.\n\nWe've been able to keep the attackers at bay, but it's time to really show 'em some muscle!\n\nHead down to the coast and start splitting some skulls!", sourceObjective = "Kill any 10 Shieldwall Forces including SI: 7 Saboteurs in and around Bilgewater Beach.", completion = "Excellent work down there, {name}! That should keep 'em outta our hair for awhile!", sourceObjectiveStatus = "unverified-source-field" }
quests[32223] = { id = 32223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Lieutenant Ethan Jacobson", description = "Wanted for crimes against the Domination Point forces!\n\nLieutenant Ethan Jacobson is responsible for leading several ground assaults against the Bilgewater lumber operation.\n\nLast spotted occupying an island south of Quickchop's Lumber Farm.", sourceObjective = "Destroy Lieutenant Ethan Jacobson in the Southern Isles south of Quickchop's Lumber Farm.", progress = "Do not return without his blood on your hands!", completion = "It's a good day when another Lion's Landing leader falls, {class}! Good work!", sourceObjectiveStatus = "unverified-source-field" }
quests[32224] = { id = 32224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise No More!", description = "Have you seen the ghosts wandering the graveyard?\n\nThey are risen ancestors, the spirits of slain mogu who have been called back to this world.\n\nWhen angered, they attack swiftly and silently, and their numbers increase by the day.\n\nThey do not belong here. Destroy them, and send them back beyond the grave.", sourceObjective = "Kill 15 Risen Ancestors.", sourceObjectiveStatus = "unverified-source-field" }
quests[32225] = { id = 32225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Thunder", description = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity.\n\nWe suspect that this weapon is meant to rain destruction on our stronghold at Dawnseeker Promontory.\n\nThere is no time to delay. You must stop their ritual at once.", sourceObjective = "Stop the Shan'ze Thundercallers' ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[32227] = { id = 32227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preventing a Future Threat", description = "The creatures the Zandalari ride don't start out so big, nor do they start out the vicious and loyal creatures they become.\n\nIf you can frighten some of the hatchling skyscreamers away from the beach, perhaps they will have a chance at a real life.", sourceObjective = "Frighten 12 Hatchling Skyscreamers by running near them.", sourceObjectiveStatus = "unverified-source-field" }
quests[32228] = { id = 32228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shuddering Moor", description = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate.\n\nStrike it down before it grows hungry enough to brave our defenses.", sourceObjective = "Kill the Mighty Devilsaur.", sourceObjectiveStatus = "unverified-source-field" }
quests[32229] = { id = 32229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Roaming Troll War Party" }
quests[32230] = { id = 32230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zandalari Colossus", description = "The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, {class}.", sourceObjective = "Destroy the Zandalari Colossus.", sourceObjectiveStatus = "unverified-source-field" }
quests[32232] = { id = 32232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Inside Counts", description = "I noticed something strange on my last scouting mission. A group of Zandalari are performing a ritual on what appears to be a very large sentry. They may be trying to re-animate it.\n\nWe need that ritual stopped and the sentry destroyed. Anything that large can't be good.\n\nI've sent a scout ahead to observe their actions. Meet with her and figure out how to stop them.", sourceObjective = "Destroy Guardian Tak'u in Conqueror's Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[32233] = { id = 32233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Very Disarming", description = "Look around you, {class}. What do you see? I see an opportunity.\n\nThe casters here work to imbue the Zandalari weapons with powerful magic. As if a sharp blade isn't enough to cut even the strongest foe down to size.\n\nIn my scouting I've noticed the weapons are not very well guarded. This is where you come in...\n\nIf we can steal a few of these weapons we may be able to use them. At the very least they are out of enemy hands.", sourceObjective = "Steal 7 Loa-Infused Blades from Conqueror's Terrace.", sourceObjectiveStatus = "unverified-source-field" }
quests[32235] = { id = 32235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flash! Aaaaaahhhh!", description = "The gnomes have brought their flying contraptions. I want my skies CLEAR!\n\nGet up there on whatever mount you have with you and destroy those paltry devices.\n\nYou may use this grog I \"acquired\" from our goblin allies. It would be better served blasting down gyrocopters than in the gullet of those little green fiends.", sourceObjective = "Use the Bilgewater Molotovs to destroy 6 Skyfire Gyrocopter X2s.", progress = "Hellscream's eyes are upon you.", completion = "Ha! Simple mechanical toys are no match for a well aimed bottle of grog.", sourceObjectiveStatus = "unverified-source-field" }
quests[32236] = { id = 32236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bug Off!", description = "This cave is crawlin' with nasty shale spiders! How's a girl supposed to get any work done with them gobbling up the miners AND the ore?!\n\nThis seemed like a good opportunity to use my newest invention, Bug Off. See, all you have to do is spray this stuff all over the shale spiders. They hate it and it doesn't seem to have many long term side-effects for the miners!\n\nWhat could possibly go wrong?\n\nTake this handy sprayer and get to work!", sourceObjective = "Spray 5 Agitated Shale Spiders with the Bug Off Sprayer and eradicate 12 Shale Shards.", progress = "Shale spiders. Why did it have to be shale spiders?!", completion = "Now that's what I like to hear! I bet those spiders will think twice before messing with a Bilgewater operation again!", sourceObjectiveStatus = "unverified-source-field" }
quests[32238] = { id = 32238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Universal Remote-Explode", description = "The Mecha-Pounders are really making things difficult down here, but I think I may have the solution!\n\nI made this universal remote for myself, but it looks like I hit a specific frequency that has an useful result!\n\nApparently this frequency weakens their armor!\n\nUse the remote to take them down a few notches then punch 'em in the face!", sourceObjective = "Destroy 9 Shieldwall Mecha-Pounders in and around Quickchop's Lumber Farm.", sourceObjectiveStatus = "unverified-source-field" }
quests[32242] = { id = 32242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Secrets", description = "I am told that the mogu once possessed hundreds of hidden armories full of earth-shattering weapons.\n\nWhen a mogu army prepared for war, they struck fear and terror into the hearts of their enemies.\n\nTHIS is the knowledge I seek here on Pandaria!\n\nI have sent an expedition to study some ruins to the west, but they work as slowly as dim-witted peons!\n\nGo speak to Fanlyr Silverthorn, their leader. Tell him that I want to see results immediately.", sourceObjective = "Speak to Fanlyr Silverthorn at Ancestral Rise in the Vale of Eternal Blossoms.", completion = "The Warchief sent you? What does he say?", sourceObjectiveStatus = "unverified-source-field" }
quests[32243] = { id = 32243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Source of Korune Power", description = "Why hullo there! Have ya ever seen tha like o' these statues? Fascinatin'!\n\nI was scouting up along the ruins earlier, and I spotted somethin' innerestin' up on the highest rise.\n\nI couldn't get close enough, but I think it might be one o' these mogu statues, 'cept it was movin'!\n\nI can't get through all those nasty blood elves, but you look like you could.\n\nWould you mind going up there and bringing me back anything of interest?", sourceObjective = "Collect a Sha-Touched Claw from the Korune Spellweaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[32244] = { id = 32244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Korune", description = "These terracotta wardens are fearsome, but not nearly as horrifying as the creature that we found at the top of the ruins.\n\nSome of our surviving scouts reported seeing some kind of mogu spellweaver on the highest rise to the north.\n\nHe practices a type of magic unlike any other we have seen.\n\nWe must learn whatever we can from this creature. Slay him, and bring me anything you find.", sourceObjective = "Collect a Korune Codex from the Korune Spellweaver.", sourceObjectiveStatus = "unverified-source-field" }
quests[32246] = { id = 32246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Scout", description = "It has been two months since the parting of the mists. Alliance scouts, seeking a suitable landing site for the fleet, have engaged Horde forces on a beach in Krasarang Wilds.\n\nMeet with Scout Lynna and help secure the landing site.", sourceObjective = "Speak with Scout Lynna at Krasarang Cove in Krasarang Wilds.", completion = "You have impeccable timing, {class}. King Wrynn is just about to land, and the full might of our fleet will follow soon after.", sourceObjectiveStatus = "unverified-source-field" }
quests[32247] = { id = 32247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A King Among Men", description = "There's no time to waste, we need to find Troteman and secure the beach.\n\nWe should check on the dwarves, too - the Explorer's League is tough, but they're no army. They should be along the cliff just north of here.\n\nLet us ride, {class}. For our friends. For the Alliance.", sourceObjective = "Accompany King Varian Wrynn to find Marshal Troteman, Hilda Hornswaggle, and slay 25 Horde.", progress = "The Alliance will be a shield, protecting Pandaria from the Horde.", completion = "I'm satisfied with this site, it's time to bring in our fleet.", sourceObjectiveStatus = "unverified-source-field" }
quests[32248] = { id = 32248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Patience", description = "King Varian needs decisive adventurers to help him resolve a showdown between Tyrande Whisperwind and a detachment of Horde warriors holed up in the Temple of the Red Crane.\n\nReport to him immediately!", sourceObjective = "Enter the \"A Little Patience\" scenario and report to King Varian Wrynn.", completion = "Good to see you again, {name}.\n\nWe have a delicate situation on our hands here. We need to plan our next moves carefully.", sourceObjectiveStatus = "unverified-source-field" }
quests[32249] = { id = 32249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Scout", description = "It has been two months since the parting of the mists. Horde scouts, seeking a suitable landing site for the fleet, have engaged Alliance forces on a small island off the coast of Krasarang Wilds.\n\nMeet with Scout Rokla and help secure the landing site.", sourceObjective = "Speak with Scout Rokla at the Horde Landing Site in Krasarang Wilds.", completion = "You are just in time. The Warchief is about to land. Once this site passes his inspection, the fleet will follow.", sourceObjectiveStatus = "unverified-source-field" }
quests[32250] = { id = 32250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of the Warchief", description = "Come, {class}! I want to inspect this island and ensure that my landing team has done their job.\n\nBlood Guard Gro'tash should be somewhere on the northern side of the island looking for a suitable place to build our keep. The goblin survey team will have gone up the eastern coast in search of oil.\n\nLet us crush this pitiful display and claim this land for the Horde!", sourceObjective = "Accompany Garrosh Hellscream to find Blood Guard Gro'tash, Grizzle Gearslip, and slay 25 Alliance.", progress = "Gorehowl thirsts for Alliance blood.", completion = "Well done. Our presence here will not be denied!", sourceObjectiveStatus = "unverified-source-field" }
quests[32251] = { id = 32251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dagger in the Dark", description = "Shadow Hunter Vol'jin has joined a group of Kor'kron scouts on an important mission for the warchief.\n\nOf course a proud member of the Horde such as yourself is welcome to go along, but be warned - it could get ugly.", sourceObjective = "Enter the \"Dagger in the Dark\" scenario and report to Vol'jin.", completion = "Good ta see ya, mon. I be needin' true allies at my side for dis mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[32252] = { id = 32252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbingers of the Loa", description = "Have you heard of the loa? We do not understand all of what it is, but it seems to be a dark magic with some degree of sentience.\n\nWe do not know what power the loa might possess, but I must ask you to put a stop to their rituals, {class}.", sourceObjective = "Slay 2 Harbingers of the Loa.", sourceObjectiveStatus = "unverified-source-field" }
quests[32254] = { id = 32254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manipulating the Saurok", description = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance.\n\nThey will be concealed from view. Look for shimmering columns of light within the saurok village.", sourceObjective = "Check in with Magister Arlan, Magister Sarien, and Magistrix Vesara.", sourceObjectiveStatus = "unverified-source-field" }
quests[32255] = { id = 32255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Constructed", description = "Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag.\n\nI want those constructs back. No slithering lizard will steal Sunreaver property under my watch.", sourceObjective = "Recover the four stolen Sunreaver Constructs.", sourceObjectiveStatus = "unverified-source-field" }
quests[32256] = { id = 32256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise Of An Empire", description = "Warchief Garrosh Hellscream travels north with a squad of his most elite soldiers.\n\nReport to him with news of our continued victory against the Alliance.\n\nSpeak to Tak-Tak for transportation.", sourceObjective = "Find Warchief Hellscream at the Shrine of Two Moons. Speak to Tak-Tak at Domination Point for transportation.", completion = "What do you have to report?", sourceObjectiveStatus = "unverified-source-field" }
quests[32257] = { id = 32257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voice of the Gods", description = "Too slowly!? We are working as quickly as possible for the Warchief!\n\nWe must excavate carefully, catalogue each find, and of course follow safety procedures. He must understand!\n\nWell, we may have something to show him soon. Do you see that stone statue to the west?\n\nWe suspect it is an ancient stone storage vessel. Now we just have to find a way to open it.\n\nIf you would care to help us with our excavation, please go about it carefully.", sourceObjective = "Investigate the Mercurial Guardian and obtain the Ancient Korune Tablet.", progress = "We are quite capable of handling this excavation. I understand the Warchief sent you, but he will get faster results if he leaves us to our work.", completion = "Hmm... very interesting. This tablet will yield many secrets, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[32262] = { id = 32262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captive Audience", description = "The Kirin Tor have gone too far! Now they hold our fellow Sunreavers as war prisoners!\n\nThere will be no discussion of prisoner exchange. We will handle this ourselves.\n\nGo to Violet Rise and free as many prisoners as you can. Do not get captured yourself. We cannot afford to lose you too.", sourceObjective = "Free 5 Sunreaver Captives around Violet Rise.", sourceObjectiveStatus = "unverified-source-field" }
quests[32264] = { id = 32264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spellbound", description = "Jaina possesses several very powerful magic artifacts. These items travel with her at all times, and are never far from her grasp. I have an interest in one of these items.\n\nA tome, filled with knowledge, passed from one archmage to another. I have only ever seen glimpses of it.\n\nNow that we fight on opposite sides I see no issue in removing the tome from her possession.", sourceObjective = "Retrieve Jaina's Weathered Spellbook from Violet Rise.", sourceObjectiveStatus = "unverified-source-field" }
quests[32265] = { id = 32265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charged Moganite", description = "We have been dispatching spies into the Kirin Tor base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here.\n\nThey have not returned, and I can confirm they have left the Kirin Tor base.\n\nSearch the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.", sourceObjective = "Recover a Charged Moganite and bring it to High Arcanist Savor.", sourceObjectiveStatus = "unverified-source-field" }
quests[32274] = { id = 32274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Residents of Ihgaluk", description = "The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction.\n\nA more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.", sourceObjective = "Slay a Skumblade Brute, a Skumblade Saur-Priest, and a Skumblade Seadragon.", sourceObjectiveStatus = "unverified-source-field" }
quests[32275] = { id = 32275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surgical Death", description = "The Zandalari train skyscreamers to become ferocious beasts in the skies. The spiritbinders require endless sacrifices - of our people - to be brought to them. And, the jaguar warriors venture ever closer toward the heart of our camp.\n\nFind them in Za'Tual and remove the threat.", sourceObjective = "Slay 3 Zandalari Spiritbinders, 3 Zandalari Beastcallers, and 3 Zandalari Jaguar Warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[32276] = { id = 32276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tear Down This Wall!", description = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon.\n\nI suppose we'll have to make a gate of our own then. Let me know when you're ready, {name}.", sourceObjective = "Speak with Lor'themar Theron, then break into the lower city and secure it for the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32277] = { id = 32277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Skies!", description = "We can use the pterrorwing that you found to strike a decisive blow against the mogu. \n\nTheir mining operation is vulnerable to attack from the air, and your pterrorwing is the only beast we have capable of flying out there.\n\nLet me know when you are ready!", sourceObjective = "Gain access to the Lightning Vein Mine.", sourceObjectiveStatus = "unverified-source-field" }
quests[32282] = { id = 32282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compy Stomp", description = "The raptors and compies of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares.\n\nI need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", sourceObjective = "Kill 5 Raptors and 10 Trained Compies in the Beast Pens.", sourceObjectiveStatus = "unverified-source-field" }
quests[32283] = { id = 32283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa-saur", description = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers.\n\nWe need to put a stop to this.\n\nSearch the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts.\n\nWe must not allow these atrocities to continue.", sourceObjective = "Defeat a Loa Speaker.", sourceObjectiveStatus = "unverified-source-field" }
quests[32284] = { id = 32284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone You Should See", sourceObjective = "Find Chen Stormstout at Binan Village. Speak to Tak-Tak at Domination Point for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32285] = { id = 32285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sleepless Legion", description = "The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.", sourceObjective = "Kill 6 Animated Warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[32286] = { id = 32286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Mogu Blood-seekers (Roaming pairs, actively fighting scouts, and performing rituals on corpses)" }
quests[32287] = { id = 32287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Beneath the Tower", description = "There are mogu in the Diremoor animating the army of statues near the tower. Lor'themar wants them dead. I think you're the one to do it.", sourceObjective = "Kill 7 Shan'ze mogu in the Diremoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[32292] = { id = 32292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Ahead!", description = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability.\n\nAnd beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city.\n\nIt's time to move out!", sourceObjective = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[32293] = { id = 32293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among the Bones", description = "My scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. I need someone capable to see him dispatched. Are you up to the task?", sourceObjective = "Kill Zur'chaka the Bonecrafter.", sourceObjectiveStatus = "unverified-source-field" }
quests[32294] = { id = 32294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raining Bones", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nWould you be willing to do the deed?", sourceObjective = "Kill Zur'chaka the Bonecrafter.", sourceObjectiveStatus = "unverified-source-field" }
quests[32295] = { id = 32295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unusual Tome", description = "The tome appears to be written in an ornate, sprawling script that seems to rise off the pages. It vaguely resembles Demonic, but the symbols are far more elaborate than any you've ever seen.\n\nPerhaps one of your demonic companions can tell you more.", sourceObjective = "Speak with your demonic minion to determine the origins of the tome.", sourceObjectiveStatus = "unverified-source-field" }
quests[32296] = { id = 32296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasures of the Thunder King", description = "My scouts have returned with word that more of the treasures from Lei Shen's tomb are being brought up into the citadel. We have access to a secret sewer entrance, but a door bars us from intercepting the shipment. If we're going to succeed in this raid, we will need a key that only the most trusted of Lei Shen's forces carry.\n\nIf you get your hands on such a key, bring it to me.\n\nYou can keep whatever spoils you steal from our raid. I simply want to see that this shipment never makes it to Lei Shen.", sourceObjective = "Speak to Taoshi to enter the Thunder King's Citadel. Inside, provide her with a Key to the Palace of Lei Shen to begin the timed raid on his treasure convoy.", sourceObjectiveStatus = "unverified-source-field" }
quests[32299] = { id = 32299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Some Light Clean-Up Work", description = "This is not a glamorous job. Let me put it to you bluntly.\n\nThe Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter.\n\nThe saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.", sourceObjective = "Disperse 75 pieces of filth by killing Quivering Filth in Ihgaluk Crag.", sourceObjectiveStatus = "unverified-source-field" }
quests[32300] = { id = 32300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarming Irony", description = "Well, it would seem the Lady Proudmoore has decided to use our own weaponry against us. Our perimeter wards reported several spies slipping through our defenses carrying tactical mana bombs.\n\nI would enjoy the irony if these bombs were less dangerous.\n\nSearch for these bombs and disarm them. Our wards reported one near the horde ships to the north, one on a bridge to the main isle, and one near our scrying crystals on the eastern side of the Promontory.", sourceObjective = "Disarm the Tactical Mana Bombs at the Horde Ships, the Scrying Crystals, and the Bridge within Dawnseeker Promontory.", sourceObjectiveStatus = "unverified-source-field" }
quests[32302] = { id = 32302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desconstruction", description = "The Kirin Tor constructs are primitive at best. Nevertheless, they pose a threat.\n\nGo to Violet Rise and dismantle Jaina's pitiful war machines. Show the Kirin Tor how easily they can be defeated!\n\nThis will be a message the Kirin Tor cannot easily ignore.", sourceObjective = "Destroy 3 Kirin Tor Constructs around Violet Rise.", sourceObjectiveStatus = "unverified-source-field" }
quests[32305] = { id = 32305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overpowered", description = "The Kirin Tor are using mana foci to empower their forces. We cannot allow this to continue.\n\nYou'll find these foci scattered around the outskirts of Violet Rise. Use this mana crystal to destroy as many as you can.\n\nEach mana focus we destroy is another small victory for our cause.", sourceObjective = "Destroy 7 Mana Foci around Violet Rise.", sourceObjectiveStatus = "unverified-source-field" }
quests[32307] = { id = 32307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reader for the Dead Tongue", description = "Return to your capital city and seek out a warlock trainer who may know more about the codex.", sourceObjective = "Bring the codex to a Warlock trainer in your capital city.", sourceObjectiveStatus = "unverified-source-field" }
quests[32309] = { id = 32309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Six Masters", description = "This book may be just the leverage we've been seeking... \n\nHow familiar are you with the Council of the Black Harvest, {name}?\n\nAfter Deathwing was defeated, six of the greatest Warlocks gathered together to teach all Warlocks advanced forms of magic stolen from our defeated foes.\n\nTake a look at the tome beside me...", sourceObjective = "Read the first chapter of the Legacy of the Masters.", sourceObjectiveStatus = "unverified-source-field" }
quests[32310] = { id = 32310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Six Masters", description = "This book may be just the leverage we've been seeking... \n\nHow familiar are you with the Council of the Black Harvest, {name}?\n\nAfter Deathwing was defeated, six of the greatest Warlocks gathered together to teach all Warlocks advanced forms of magic stolen from our defeated foes.\n\nTake a look at the tome beside me...", sourceObjective = "Read the first chapter of the Legacy of the Masters.", sourceObjectiveStatus = "unverified-source-field" }
quests[32315] = { id = 32315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anduin's Plea", description = "Ah, just the {class} I was looking for. I have received an urgent letter from the young Prince Anduin.\n\nHe is playing host to his father, King Wrynn, and several other Alliance dignitaries at the Shrine of Seven Stars in the Vale of Eternal Blossoms.\n\nAccording to his most recent correspondence, something bad is happening at the city.\n\nPlease go at once and speak with him. I must settle some affairs here at Lion's Landing, but I will join you soon.\n\nSpeak to Fennie if you'd like a ride to the Vale.", sourceObjective = "Find Anduin at the Shrine of Seven Stars. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", sourceObjectiveStatus = "unverified-source-field" }
quests[32316] = { id = 32316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart Of The Alliance", description = "I can't believe this has happened, {name}. After all we have been through here on Pandaria, will our people never learn from their past mistakes?\n\nBrann's expedition returned recently from Mogujia, bearing a sample of sha for study.\n\nI had my reservations about this endeavor in the first place, and my worst fears have been realized.\n\nThe sha has escaped containment. I do not need to explain the horror of bringing the sha into the heart of the Vale.\n\nWe must dispel any sha we can find, and quickly!", sourceObjective = "Confront 6 Sha-Touched Footmen. Should you lose Prince Anduin, speak to him at The Imperial Exchange.", sourceObjectiveStatus = "unverified-source-field" }
quests[32317] = { id = 32317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking the Soulstones", description = "{name}, take this - the journal of Jubeka Shadowbreaker.\n\nRead the journal and use the information contained within to track down where she went.\n\nFind her soulstones and use them to locate her.", sourceObjective = "Read Jubeka's Journal and use the clues within to locate the four soulstone fragments.", sourceObjectiveStatus = "unverified-source-field" }
quests[32318] = { id = 32318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regeneration Takes Time", description = "Vol'jin would be dead if he were any race other than a troll. His regeneration is impressive, but it is being blocked by a poison.\n\nWe need to cleanse this poison so that he can regenerate the damage.\n\nTake to the skies and travel southeast. Across the mountain tops of the Secret Aerie you will find needle sprites. Bring me some of the hardest needles from them you can find.\n\nWith them I can attempt an acupuncture technique that should purge the poison from his body and accelerate his regeneration.", sourceObjective = "Collect 10 Sturdy Needles.", sourceObjectiveStatus = "unverified-source-field" }
quests[32319] = { id = 32319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Thrall!", description = "<Vol'jin half opens an eye and begins to move his lips as if to speak.  Though no sound comes, you decipher two words.>\n\nFind Thrall.\n\n<With an effort, Vol'jin thrusts a hearthstone into your hands and then passes out.>", sourceObjective = "Find Thrall by using Vol'jin's Hearthstone.", sourceObjectiveStatus = "unverified-source-field" }
quests[32320] = { id = 32320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Is Family", sourceObjective = "Escort Thrall to the Echo Isles.", sourceObjectiveStatus = "unverified-source-field" }
quests[32321] = { id = 32321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Monkey King", description = "Ever since the Horde captured the Divine Bell I have been searching for a means to counter its power.\n\nMy research got as far as this tomb. I am going inside. If you follow me, I will share the rest as we go.\n\nIf we get separated, meet me back here at the entrance to the tomb. Speak to me when you are ready to proceed.", sourceObjective = "Help Anduin Wrynn find the Monkey King in the Valley of Emperors.", sourceObjectiveStatus = "unverified-source-field" }
